import{z as s,x as i,o as A,c as n,q as t,j as r,D as a,d as B,s as o,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"端侧硬件谱系","description":"","frontmatter":{"title":"端侧硬件谱系","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/edge-hardware-spectrum.md","filePath":"llm/edge-hardware-spectrum.md","lastUpdated":1791063341000}'),p={name:"llm/edge-hardware-spectrum.md"};function m(D,E,C,F,P,h){const l=i("Mermaid");return A(),n("div",null,[E[2]||(E[2]=t('<h1 id="端侧硬件谱系" tabindex="-1">端侧硬件谱系 <a class="header-anchor" href="#端侧硬件谱系" aria-label="Permalink to &quot;端侧硬件谱系&quot;">​</a></h1><div class="epigraph"><p>端侧不是一台缩小版服务器：同一块 SoC 上 CPU、GPU、NPU 各拿各的预算，选错执行单元，带宽账从第一层就错。</p><footer>—— 据 Apple、Qualcomm、MediaTek 公开 SoC 规格与屋顶线分析口径整理</footer></div><p><a href="/llm/diff-map">上一课</a>把扩散生成的服务化收成一条成本公式——前向次数 × 单前向成本 ÷ 批效率，加固定段——和一套「症状到层、层到旋钮」的排查协议，算的都是数据中心里的加速卡。权重一旦发布，还要落到另一类机器：用户手里的设备。本课程把视角移到后者。端侧推理深入的第一课先钉坐标系：手机、笔记本、开发板、车机的预算在哪些维度上差出数量级，后课的工具链、量化、内存与能耗预算都在这套坐标系里取值。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>云端把内存、带宽、算力都当可扩容资源，不够就换卡。端侧三者焊死在 SoC 上，还有第四条约束：散热与电池决定「能持续多久」。缺口因此不是「哪颗芯片快」，而是把 8 GB 内存手机、统一内存的轻薄本、带 GPU 的开发板放进同一张表：内存容量、内存带宽、峰值算力、支持的数值精度、持续功耗。decode 的时间下界由权重搬运给出：\\(t_{\\mathrm{decode}} \\gt N_{\\mathrm{bytes}} / B\\)，\\(B\\) 是有效带宽。4 GB 的 4-bit 八十亿参数模型，在 50 GB/s 的手机内存上每 token 至少 80 ms；<a href="/llm/arithmetic-intensity-decode">解码的算术强度</a>已解释为何这一项压不住算力。prefill 才偏算力：\\(t_{\\mathrm{prefill}} \\approx 2 N_{\\mathrm{params}} \\cdot n / F\\)。两个阶段绑两种资源，端侧把这两种饥饿压在同一块发热的芯片上。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>谱系分四档。手机 SoC：大小核 CPU、GPU、NPU 并存，LPDDR 带宽几十 GB/s，内存 6–16 GB，<a href="/llm/mobile-npu-deploy">移动端 NPU 部署</a>已给出它的执行单元分工。第二档是统一内存桌面：Apple Silicon 与带 NPU 的 x86 笔记本，容量与带宽高一个档位，<a href="/llm/mlx-apple">Apple MLX</a> 正是利用统一内存免去拷贝。第三档是嵌入式与开发板：GPU 有算力但内存共享且带宽窄。第四档车机与可穿戴，预算再降。<span class="marginnote">同一公式换个档位代入：手机 LPDDR 约 50 GB/s，4 GB 权重的 decode 下界是 80 毫秒；统一内存桌面带宽约 200 GB/s，同样权重下界降到 20 毫秒（每秒约 50 token）。模型一个字没改，只把设备从手机档换到桌面档，速度就差四倍——全差在带宽这一项上。</span>每档对应不同的可行模型规模与切分策略，后课不再重复这张表。</p>',7)),(A(),r(d,null,{default:a(()=>[o(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%AB%AF%E4%BE%A7%E8%AE%BE%E5%A4%87%E6%A1%A3%E4%BD%8D%22%5D%20--%3E%20B%5B%22%E6%89%8B%E6%9C%BA%20SoC%3A%20LPDDR%20%E5%87%A0%E5%8D%81%20GB%2Fs%22%5D%0A%20%20A%20--%3E%20C%5B%22%E7%BB%9F%E4%B8%80%E5%86%85%E5%AD%98%E6%A1%8C%E9%9D%A2%3A%20UMA%20%E4%B8%8A%E7%99%BE%20GB%2Fs%22%5D%0A%20%20A%20--%3E%20D%5B%22%E5%BC%80%E5%8F%91%E6%9D%BF%3A%20%E7%AE%97%E5%8A%9B%E6%9C%89%20%E5%86%85%E5%AD%98%E7%AA%84%22%5D%0A%20%20A%20--%3E%20E%5B%22%E8%BD%A6%E6%9C%BA%E4%B8%8E%E5%8F%AF%E7%A9%BF%E6%88%B4%3A%20%E9%A2%84%E7%AE%97%E6%9C%80%E7%B4%A7%22%5D%0A%20%20B%20--%3E%20F%5B%22decode%20%E4%B8%8B%E7%95%8C%20%3D%20%E5%AD%97%E8%8A%82%20%2F%20%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20C%20--%3E%20F%0A%20%20D%20--%3E%20F%0A%20%20E%20--%3E%20F%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"带宽是第一约束的机理：每生成一个 token，权重都要从内存完整读一遍，参数读不进片上缓存；算力却能靠量化、稀疏与好 kernel 省。所以选设备的正确顺序是先看容量与带宽，再看 TOPS。把 TOPS 当唯一指标必然错：NPU 宣传的峰值算力是稀疏、低精度下的理论值，与「每秒能搬多少字节」无关——一颗四十几 TOPS 的 NPU 配三十几 GB/s 的内存，decode 速度仍由后者决定。统一内存的价值同理：不只是带宽更高，而是 CPU、GPU、NPU 共享同一份物理页，权重不必复制，换执行单元不用搬数据。",-1)),E[5]||(E[5]=e("p",null,[e("span",{class:"marginnote"},"数量级锚点：HBM3 带宽约 3 TB/s，旗舰手机 LPDDR5X 约 50–100 GB/s，差三四十倍。同一个 8B 模型云端每秒几百 token、手机每秒十几 token，主要不是算力差这么多，是搬运差这么多。")],-1)),E[6]||(E[6]=e("p",null,"评估一台设备能跑什么模型，正确顺序是容量、带宽、算力：",-1)),(A(),r(d,null,{default:a(()=>[o(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BF%99%E5%8F%B0%E8%AE%BE%E5%A4%87%E8%83%BD%E8%B7%91%E5%A4%9A%E5%A4%A7%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20M%7B%22%E5%AE%B9%E9%87%8F%EF%BC%9A%E6%9D%83%E9%87%8D%E5%8A%A0%20KV%20%E8%A3%85%E5%BE%97%E4%B8%8B%EF%BC%9F%22%7D%0A%20%20M%20--%3E%7C%E8%A3%85%E4%B8%8D%E4%B8%8B%7C%20A%5B%22%E5%85%88%E9%87%8F%E5%8C%96%E6%88%96%E6%8D%A2%E6%9B%B4%E5%B0%8F%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20M%20--%3E%7C%E8%A3%85%E5%BE%97%E4%B8%8B%7C%20B%7B%22%E5%B8%A6%E5%AE%BD%EF%BC%9Adecode%20%E4%B8%8B%E7%95%8C%E5%8F%AF%E6%8E%A5%E5%8F%97%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E5%AD%97%E8%8A%82%E6%95%B0%20%2F%20%E5%B8%A6%E5%AE%BD%20%E5%A4%AA%E6%85%A2%22%7C%20A2%5B%22%E9%99%8D%E6%AF%94%E7%89%B9%EF%BC%8C%E6%88%96%E4%B8%8A%E6%9B%B4%E9%AB%98%E5%B8%A6%E5%AE%BD%E6%A1%A3%22%5D%0A%20%20B%20--%3E%7C%E5%8F%AF%E6%8E%A5%E5%8F%97%7C%20T%7B%22%E7%AE%97%E5%8A%9B%EF%BC%9Aprefill%20%E4%B8%8E%E9%A6%96%20token%20%E8%BE%BE%E6%A0%87%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%E6%98%AF%7C%20OK%5B%22%E5%AE%9A%E6%A1%A3%EF%BC%9A%E5%86%99%E5%85%A5%E8%AF%84%E6%B5%8B%E7%9F%A9%E9%98%B5%22%5D%0A%20%20T%20--%3E%7C%E5%90%A6%7C%20A3%5B%22%E7%83%AD%E7%82%B9%E6%94%BE%20NPU%20%E6%88%96%E7%BC%A9%E7%9F%AD%E8%BE%93%E5%85%A5%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">带宽和算力可以类比供水系统：TOPS 是水厂的处理能力，内存带宽是水管的粗细。decode 像「每出一杯水都要把整个水库重新运一遍」——水管细，水厂再强也白搭。所以选设备的口诀是先看水管（带宽与容量），再看水厂（TOPS），顺序反了预算就从第一层算错。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课给坐标系，不给芯片排行：具体型号迭代太快，数量级关系才稳定。<span class="marginnote">初学者容易把「统一内存」理解成「内存更大」。它的核心价值是 CPU、GPU、NPU 共享同一份物理内存：权重在整机里只有一份，切换执行单元不用拷贝数据；传统架构里每个单元各有自己的显存或内存副本，光把权重复制一遍就能吃掉好几个 GB——在 8 GB 的设备上这就是能不能跑的差别。</span>散热为什么让「持续性能」低于「峰值性能」，留给能耗预算课；同一颗芯片上模型能不能编译进 NPU，留给下一课的工具链。云侧对应的带宽与显存账在 KV 与调度各课已算过，本课不重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>端侧第一约束是内存容量与带宽，decode 下界 \\(N_{\\mathrm{bytes}}/B\\)；TOPS 是第二位指标。</li><li>谱系四档：手机 SoC、统一内存桌面、开发板、车机穿戴，每档对应不同可行规模。</li><li>prefill 偏算力、decode 偏带宽，端侧把两种饥饿压在同一个散热约束下。</li><li>统一内存省的是拷贝与物理页复制，不只是带宽数字。</li><li>出处：据 Apple、Qualcomm、MediaTek 公开 SoC 规格与屋顶线分析口径整理；执行单元分工见本站移动端 NPU 部署课。</li></ul>',5))])}const u=s(p,[["render",m]]);export{f as __pageData,u as default};
